<?php declare(strict_types=1);require_once __DIR__.'/bootstrap.php';function portal_user():?array{if(empty($_SESSION['portal_user_id']))return null;global $db;$q=$db->prepare('SELECT id,client_id,email,first_name,last_name,is_active FROM client_portal_users WHERE id=? LIMIT 1');$q->execute([(int)$_SESSION['portal_user_id']]);$u=$q->fetch();return ($u&&$u['is_active'])?$u:null;}function portal_require():array{$u=portal_user();if(!$u){header('Location: login.php');exit;}return $u;}function portal_login(int $id):void{session_regenerate_id(true);$_SESSION['portal_user_id']=$id;$_SESSION['portal_csrf']=bin2hex(random_bytes(32));}function portal_logout():void{$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',['expires'=>time()-42000,'path'=>$p['path'],'domain'=>$p['domain'],'secure'=>$p['secure'],'httponly'=>$p['httponly'],'samesite'=>'Lax']);}session_destroy();}